from pwn import *
import string

# Constants from the MBR (at offset 0x1A0)
constants = [
    0x0270, 0x0211, 0x0255, 0x0229,
    0x0291, 0x025e, 0x0233, 0x01f9,
    0x0278, 0x027b, 0x0221, 0x0209,
    0x025d, 0x0290, 0x028f, 0x02df
]

def validate_char(pos, char, prev):
    # Simulate SSE operations in the MBR
    val = ord(char)
    # Left rotation by 8 bits (as seen in the SSE PSHUFD)
    rotated = ((val << 8) | (val >> 8)) & 0xFFFF
    # XOR with position-based constant
    if pos > 0:
        rotated ^= constants[pos - 1]
    return rotated == constants[pos]

def solve_flag():
    known = "flag{"  # We know it starts with this
    result = list(known + "?"*10 + "}")

    # Find each character position
    for pos in range(5, 15):
        for c in string.printable:
            if validate_char(pos, c, result[pos-1]):
                result[pos] = c
                break

    return ''.join(result)

def verify_flag(flag):
    # Check length
    if len(flag) != 16:
        return False

    # Check prefix and suffix
    if not flag.startswith("flag{") or not flag.endswith("}"):
        return False

    # Verify each character against constants
    for i in range(5, 15):
        if not validate_char(i, flag[i], flag[i-1]):
            return False

    return True

# Try to find the flag
flag = solve_flag()
print(f"Found potential flag: {flag}")

# Verify the solution
if verify_flag(flag):
    print("Flag verified as correct!")
else:
    print("Flag verification failed!")

